{"command":"python3 - << 'PY'
import sys; sys.path.insert(0,"/tmp")
from probe import *
import pathlib, shutil, struct
def trial(raw, label):
    D="/tmp/zocorr2/data"; shutil.rmtree("/tmp/zocorr2",ignore_errors=True); pathlib.Path(D).mkdir(parents=True); pathlib.Path(D+"/db.zo").write_bytes(raw)
    r=run(["query","x"],data=D); print(label, repr(r.stderr))
def ent(pathlen, s):
    return struct.pack("<I",3)+struct.pack("<Q",1)+struct.pack("<Q",pathlen)+s
for pl,s in [(4,b"/tmp"),(5,b"/tmp"),(5,b"/tmpX"),(100,b"/tmp"),(100,b""),(1,b""),(0,b""),(10,b"/tmp"+b"\x00"*16)]:
    trial(ent(pl,s), f"pathlen={pl} s={s!r}")
# invalid utf8 variants
for s in [b"\xff", b"a\xff", b"\xc3\x28", b"ab\xff\xfe", b"\xe2\x82"]:
    raw=struct.pack("<I",3)+struct.pack("<Q",1)+struct.pack("<Q",len(s))+s+struct.pack("<d",1)+struct.pack("<Q",1)
    trial(raw, f"utf8 {s!r}")
PY
"}

