{"command":"python3 - << 'PY'
import subprocess, os, json, zlib, base64
shells=["bash","elvish","fish","nushell","posix","powershell","tcsh","xonsh","zsh"]
hooks=["none","prompt","pwd"]
out={}
for shell in shells:
 for hook in hooks:
  for echo in [0,1]:
   for res in [0,1]:
    for nocmd in [0,1]:
        env=dict(os.environ); [env.pop(k,None) for k in list(env) if k.startswith("_ZO")]
        if echo: env["_ZO_ECHO"]="1"
        if res: env["_ZO_RESOLVE_SYMLINKS"]="1"
        args=["/workspace/executable","init",shell,"--hook",hook,"--cmd","__ZO_CMD_PLACEHOLDER__"]
        if nocmd: args.append("--no-cmd")
        r=subprocess.run(args,capture_output=True,text=True,env=env)
        assert r.returncode==0, (args,r.stderr)
        out[f"{shell}|{hook}|{echo}|{res}|{nocmd}"]=r.stdout
raw=json.dumps(out,separators=(",",":")).encode()
comp=zlib.compress(raw,9)
print("templates",len(out),"raw",len(raw),"zlib",len(comp),"b85",len(base64.b85encode(comp)))
# check placeholders count and no-cmd placeholder presence
for k,v in out.items():
    if "__ZO_CMD_PLACEHOLDER__" in v and k.endswith("|1"):
        print("nocmd has placeholder",k)
print("sample placeholder counts", [(k,v.count("__ZO_CMD_PLACEHOLDER__")) for k,v in list(out.items())[:5]])
# alternative store only unique texts
uniq={}
for k,v in out.items(): uniq.setdefault(v,[]).append(k)
print("unique texts",len(uniq))
raw2=json.dumps(list(uniq.keys())).encode(); print("unique raw",len(raw2),"comp",len(zlib.compress(raw2,9)))
PY
"}

