# Database


class DirEntry:
    __slots__ = ("path", "rank", "last_accessed")

    def __init__(self, path, rank, last_accessed):
        self.path = path
        self.rank = float(rank)
        self.last_accessed = int(last_accessed)

    def score(self, now):
        age = now - self.last_accessed if now >= self.last_accessed else 0
        if age < 3600:
            weight = 4.0
        elif age < 86400:
            weight = 2.0
        elif age < 604800:
            weight = 0.5
        else:
            weight = 0.25
        return self.rank * weight


class Database:
    def __init__(self, data_dir, db_path, dirs):
        self.data_dir = data_dir
        self.db_path = db_path
        self.dirs = dirs
        self.modified = False

    @classmethod
    def open(cls):
        data_dir = get_data_dir()
        db_path = join_path(data_dir, "db.zo")
        try:
            with open(db_path, "rb") as handle:
                contents = handle.read()
        except FileNotFoundError:
            try:
                os.makedirs(data_dir, exist_ok=True)
            except OSError as exc:
                raise ZoxideError(
                    f"unable to create data directory: {display_path(data_dir)}",
                    [os_error_string(exc)],
                )
            return cls(data_dir, db_path, [])
        except OSError as exc:
            raise ZoxideError(
                f"could not read from database: {display_path(db_path)}",
                [os_error_string(exc)],
            )

        if len(contents) < 4:
            raise ZoxideError("could not deserialize database: corrupted data")
        (version,) = struct.unpack_from("<I", contents, 0)
        if version != 3:
            raise ZoxideError(f"unsupported version (got {version}, supports 3)")

        offset = 4

        def fail(cause):
            raise ZoxideError("could not deserialize database", [cause])

        def read_primitive(fmt):
            nonlocal offset
            size = struct.calcsize(fmt)
            if offset + size > len(contents):
                fail("io error: unexpected end of file")
            (value,) = struct.unpack_from(fmt, contents, offset)
            offset += size
            return value

        count = read_primitive("<Q")
        dirs = []
        for _ in range(count):
            path_len = read_primitive("<Q")
            if offset + path_len > len(contents):
                fail("io error: ")
            raw_path = contents[offset : offset + path_len]
            offset += path_len
            try:
                path = raw_path.decode("utf-8")
            except UnicodeDecodeError:
                fail(f"string is not valid utf8: {rust_utf8_error(raw_path)}")
            rank = read_primitive("<d")
            last_accessed = read_primitive("<Q")
            dirs.append(DirEntry(path, rank, last_accessed))
        if offset != len(contents):
            fail("Slice had bytes remaining after deserialization")
        return cls(data_dir, db_path, dirs)

    def serialize(self):
        out = [struct.pack("<I", 3), struct.pack("<Q", len(self.dirs))]
        for entry in self.dirs:
            raw = entry.path.encode("utf-8", "surrogateescape")
            out.append(struct.pack("<Q", len(raw)))
            out.append(raw)
            out.append(struct.pack("<d", entry.rank))
            out.append(struct.pack("<Q", entry.last_accessed & ((1 << 64) - 1)))
        return b"".join(out)

    def save(self):
        if not self.modified:
            return
        payload = self.serialize()
        alphabet = string.ascii_letters + string.digits
        suffix = "".join(random.SystemRandom().choice(alphabet) for _ in range(12))
        tmp_path = join_path(self.data_dir, f"tmp_{suffix}")
        try:
            handle = open(tmp_path, "wb")
        except OSError as exc:
            raise ZoxideError(
                "could not write to database",
                [f"could not create file: {display_path(tmp_path)}", os_error_string(exc)],
            )
        try:
            with handle:
                handle.write(payload)
        except OSError as exc:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise ZoxideError(
                "could not write to database",
                [f"could not write to file: {display_path(tmp_path)}", os_error_string(exc)],
            )
        try:
            os.replace(tmp_path, self.db_path)
        except OSError as exc:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise ZoxideError(
                "could not write to database",
                [f"could not rename file: {display_path(tmp_path)}", os_error_string(exc)],
            )
        self.modified = False

    def save_silently(self):
        try:
            self.save()
        except Exception:
            pass

    def _swap_remove(self, index):
        last = self.dirs.pop()
        if index < len(self.dirs):
            self.dirs[index] = last

    def find(self, path):
        for index, entry in enumerate(self.dirs):
            if entry.path == path:
                return index
        return None

    def add(self, path, by, now):
        index = self.find(path)
        if index is not None:
            entry = self.dirs[index]
            entry.rank = rust_max(entry.rank + by, 0.0)
            entry.last_accessed = now
        else:
            self.dirs.append(DirEntry(path, rust_max(by, 0.0), now))
        self.modified = True

    def edit_adjust(self, path, by, now):
        index = self.find(path)
        if index is not None:
            entry = self.dirs[index]
            entry.rank = rust_max(entry.rank + by, 0.0)
        else:
            self.dirs.append(DirEntry(path, rust_max(by, 0.0), now))
        self.modified = True

    def remove_exact(self, path):
        index = self.find(path)
        if index is None:
            return False
        self._swap_remove(index)
        self.modified = True
        return True

    def sort_by_score(self, now):
        self.dirs.sort(key=lambda entry: total_cmp_key(entry.score(now)))
        self.modified = True

    def dedup(self):
        self.dirs.sort(key=lambda entry: entry.path.encode("utf-8", "surrogateescape"))
        for i in range(len(self.dirs) - 1, 0, -1):
            if i >= len(self.dirs):
                continue
            if self.dirs[i - 1].path == self.dirs[i].path:
                self.dirs[i - 1].rank += self.dirs[i].rank
                if self.dirs[i].last_accessed > self.dirs[i - 1].last_accessed:
                    self.dirs[i - 1].last_accessed = self.dirs[i].last_accessed
                self._swap_remove(i)

    def age(self, maxage):
        total = 0.0
        for entry in self.dirs:
            total += entry.rank
        if not (total > float(maxage)):
            return
        factor = 0.9 * float(maxage) / total
        for i in range(len(self.dirs) - 1, -1, -1):
            if i >= len(self.dirs):
                continue
            self.dirs[i].rank *= factor
            if self.dirs[i].rank < 1.0:
                self._swap_remove(i)


