class _ClapErrors:
    def __init__(self, bin_name):
        self.bin = bin_name

    def exit(self, text):
        raise CliExit(2, stderr=text)

    def generic(self, message, usage, tip=None):
        text = f"error: {message}\n"
        if tip:
            text += f"\n  tip: {tip}\n"
        text += f"\nUsage: {usage}\n\nFor more information, try '--help'.\n"
        self.exit(text)

    def no_usage(self, message, possible=None, tip=None):
        text = f"error: {message}\n"
        if possible:
            text += f"  [possible values: {', '.join(possible)}]\n"
        if tip:
            text += f"\n  tip: {tip}\n"
        text += "\nFor more information, try '--help'.\n"
        self.exit(text)


class Parser:
    def __init__(self, spec, bin_name):
        self.spec = spec
        self.bin = bin_name
        self.errors = _ClapErrors(bin_name)
        self.values = {}
        self.positionals = []
        self.seen = set()
        self.used = []  # option ids, in encounter order

    # ----- usage helpers -------------------------------------------------
    def _option_by_id(self, id):
        if id == "__help":
            return _HELP_OPT
        if id == "__version":
            return _VERSION_OPT
        for option in self.spec.options:
            if option.id == id:
                return option
        return None

    def smart_usage(self, extra_id=None, exclude_id=None):
        if not self.used and not self.positionals and extra_id is None:
            return self.spec.full_usage(self.bin)
        parts = [self.bin] + self.spec.path
        option_ids = []
        # Required options come first in clap's generated usage.
        for option in self.spec.options:
            if option.required and option.id != exclude_id:
                option_ids.append(option.id)
        for id in self.used:
            if id != exclude_id and id not in option_ids:
                option_ids.append(id)
        if extra_id is not None and extra_id != exclude_id and extra_id not in option_ids:
            option_ids.append(extra_id)
        for id in option_ids:
            option = self._option_by_id(id)
            if option is not None:
                parts.append(option.render)
        if self.spec.key == "top":
            parts.append("<COMMAND>")
        elif self.spec.positional is not None:
            positional = self.spec.positional
            if self.positionals or positional.required:
                parts.append(positional.required_display)
            else:
                parts.append(positional.display)
        return " ".join(parts)

    # ----- individual error constructors ---------------------------------
    def help_exit(self):
        raise CliExit(0, stdout=_help_text(self.spec.key, self.bin))

    def version_exit(self):
        raise CliExit(0, stdout=f"{_VERSION_NAMES[self.spec.key]} {VERSION}\n")

    def invalid_utf8(self):
        self.errors.generic(
            "invalid UTF-8 was detected in one or more arguments",
            self.spec.full_usage(self.bin),
        )

    def value_required_option(self, option):
        self.errors.no_usage(
            f"a value is required for '{option.display}' but none was supplied",
            possible=option.possible,
        )

    def value_required_positional(self, positional):
        self.errors.no_usage(
            f"a value is required for '{positional.display}' but none was supplied",
            possible=positional.possible,
        )

    def invalid_enum(self, display, raw, possible):
        shown = lossy(raw)
        candidates = _did_you_mean(shown, possible)
        tip = f"a similar value exists: '{candidates[-1]}'" if candidates else None
        self.errors.no_usage(
            f"invalid value '{shown}' for '{display}'", possible=possible, tip=tip
        )

    def repeated(self, option):
        self.errors.generic(
            f"the argument '{option.display}' cannot be used multiple times",
            self.spec.full_usage(self.bin),
        )

    def unexpected_value(self, option, value):
        usage = self.smart_usage(extra_id=option.id)
        self.errors.generic(
            f"unexpected value '{lossy(value)}' for '--{option.long}' found; no more were expected",
            usage,
        )

    def unknown_long(self, name):
        shown = lossy(name)
        candidates = _did_you_mean(shown, [opt.long for opt in self.spec.all_options()])
        display = f"--{shown}"
        if candidates:
            candidate = candidates[-1]
            option = None
            for opt in self.spec.all_options():
                if opt.long == candidate:
                    option = opt
                    break
            usage = self.smart_usage(extra_id=option.id if option else None)
            self.errors.generic(
                f"unexpected argument '{display}' found",
                usage,
                tip=f"a similar argument exists: '--{candidate}'",
            )
        tip = None
        if self.spec.positional is not None:
            tip = f"to pass '{display}' as a value, use '-- {display}'"
        self.errors.generic(
            f"unexpected argument '{display}' found",
            self.smart_usage(),
            tip=tip,
        )

    def unknown_short(self, ch):
        shown = lossy(ch)
        display = f"-{shown}"
        tip = None
        if self.spec.positional is not None:
            tip = f"to pass '{display}' as a value, use '-- {display}'"
        self.errors.generic(
            f"unexpected argument '{display}' found",
            self.spec.full_usage(self.bin),
            tip=tip,
        )

    def unexpected_positional(self, token):
        self.errors.generic(
            f"unexpected argument '{lossy(token)}' found",
            self.spec.full_usage(self.bin),
        )

    # ----- value assignment ------------------------------------------------
    def assign_option(self, option, raw):
        if raw == "" and not option.allow_empty:
            self.value_required_option(option)
        if option.kind == "enum":
            shown = lossy(raw)
            if shown not in option.possible:
                self.invalid_enum(option.display, shown, option.possible)
            self.values[option.id] = shown
            return
        if has_surrogates(raw):
            self.invalid_utf8()
        if option.kind == "float":
            try:
                self.values[option.id] = parse_rust_f64(raw)
            except ValueError as exc:
                self.errors.no_usage(
                    f"invalid value '{raw}' for '{option.display}': {exc}"
                )
            return
        self.values[option.id] = raw

    def assign_positional(self, token):
        positional = self.spec.positional
        if positional is None:
            self.unexpected_positional(token)
        if not positional.multi and self.positionals:
            self.unexpected_positional(token)
        if token == "" and not positional.allow_empty:
            self.value_required_positional(positional)
        if positional.kind == "enum":
            shown = lossy(token)
            if shown not in positional.possible:
                self.invalid_enum(positional.display, shown, positional.possible)
            self.positionals.append(shown)
            return
        if positional.kind == "string" and has_surrogates(token):
            self.invalid_utf8()
        self.positionals.append(token)

    def _classify_flag_token(self, token):
        if token == "--":
            return "separator"
        if token.startswith("--") and len(token) > 2:
            name = token[2:].split("=", 1)[0]
            if name in [opt.long for opt in self.spec.all_options()]:
                return "known"
            return "unknown"
        if token.startswith("-") and len(token) > 1:
            for ch in token[1:]:
                if ch in ("h", "V"):
                    continue
                option = self.spec.find_short(ch)
                if option is None:
                    return "unknown"
                if option.takes_value:
                    return "known"
            return "known"
        return "value"

    def _next_option_value(self, option, args, i):
        """Return (value, new_index) for an option at args[i] with no '='."""
        if i + 1 >= len(args):
            self.value_required_option(option)
        nxt = args[i + 1]
        if nxt == "--":
            self.value_required_option(option)
        if nxt.startswith("-") and len(nxt) > 1:
            classification = self._classify_flag_token(nxt)
            if classification == "known":
                self.value_required_option(option)
            # Unknown flag-like tokens are reported as the unexpected
            # argument itself (this is how `--score -1` behaves).
            if nxt.startswith("--"):
                self.unknown_long(nxt[2:].split("=", 1)[0])
            else:
                # Report the first unknown short character.
                for ch in nxt[1:]:
                    if ch in ("h", "V"):
                        continue
                    option2 = self.spec.find_short(ch)
                    if option2 is None:
                        self.unknown_short(ch)
                    if option2.takes_value:
                        break
                self.unknown_short(nxt[1])
        return nxt, i + 2

    def parse(self, args):
        i = 0
        end_options = False
        while i < len(args):
            token = args[i]
            if not end_options and token == "--":
                end_options = True
                i += 1
                continue

            if not end_options and token.startswith("--") and len(token) > 2:
                body = token[2:]
                if "=" in body:
                    name, eq_value = body.split("=", 1)
                    has_eq = True
                else:
                    name, eq_value, has_eq = body, None, False
                if name == "help":
                    if has_eq:
                        self.unexpected_value(_HELP_OPT, eq_value)
                    self.help_exit()
                if name == "version":
                    if has_eq:
                        self.unexpected_value(_VERSION_OPT, eq_value)
                    self.version_exit()
                option = self.spec.find_long(name)
                if option is None:
                    self.unknown_long(name)
                if option.id in self.seen:
                    self.repeated(option)
                self.seen.add(option.id)
                if not option.takes_value:
                    if has_eq:
                        self.unexpected_value(option, eq_value)
                    self.values[option.id] = True
                    self.used.append(option.id)
                    i += 1
                else:
                    if has_eq:
                        raw = eq_value
                        i += 1
                    else:
                        raw, i = self._next_option_value(option, args, i)
                    self.assign_option(option, raw)
                    self.used.append(option.id)
                continue

            if not end_options and token.startswith("-") and len(token) > 1:
                cluster = token[1:]
                pos = 0
                consumed_next = False
                while pos < len(cluster):
                    ch = cluster[pos]
                    if ch == "h":
                        self.help_exit()
                    if ch == "V":
                        self.version_exit()
                    option = self.spec.find_short(ch)
                    if option is None:
                        self.unknown_short(ch)
                    if option.id in self.seen:
                        self.repeated(option)
                    self.seen.add(option.id)
                    if not option.takes_value:
                        self.values[option.id] = True
                        self.used.append(option.id)
                        pos += 1
                        continue
                    rest = cluster[pos + 1 :]
                    if rest != "":
                        raw = rest[1:] if rest.startswith("=") else rest
                        self.assign_option(option, raw)
                        self.used.append(option.id)
                        pos = len(cluster)
                    else:
                        raw, next_i = self._next_option_value(option, args, i)
                        self.assign_option(option, raw)
                        self.used.append(option.id)
                        consumed_next = True
                        i = next_i
                        pos = len(cluster)
                if not consumed_next:
                    i += 1
                continue

            self.assign_positional(token)
            i += 1

        self._validate_conflicts()
        self._validate_required()
        return self.values, self.positionals

    def _validate_conflicts(self):
        if self.spec.key != "query":
            return
        if "interactive" in self.values and "list" in self.values:
            first = "interactive" if self.used.index("interactive") < self.used.index("list") else "list"
            second = "list" if first == "interactive" else "interactive"
            usage = self.smart_usage(exclude_id=second)
            self.errors.generic(
                f"the argument '--{first}' cannot be used with '--{second}'", usage
            )

    def _validate_required(self):
        missing = []  # (id or None, display)
        for option in self.spec.options:
            if option.required and option.id not in self.values:
                missing.append((option.id, option.display))
        positional = self.spec.positional
        if positional is not None and positional.required and not self.positionals:
            missing.append((None, positional.display))
        if not missing:
            return
        lines = "\n".join(f"  {display}" for _, display in missing)
        text = (
            "error: the following required arguments were not provided:\n"
            f"{lines}\n\nUsage: {self.smart_usage()}\n\n"
            "For more information, try '--help'.\n"
        )
        self.errors.exit(text)


def _unknown_subcommand(bin_name, parent_key, token, candidates, usage):
    shown = lossy(token)
    suggestions = _did_you_mean(shown, candidates)
    tip = _format_suggestions(suggestions, "subcommand") if suggestions else None
    errors = _ClapErrors(bin_name)
    errors.generic(f"unrecognized subcommand '{shown}'", usage, tip=tip)


