"""A reimplementation of the zoxide command-line tool.

The implementation is deliberately self-contained apart from the shell
initialisation texts in :mod:`init_templates`.
"""

import errno
import math
import os
import pwd
import random
import re
import string
import struct
import subprocess
import sys
import time

try:
    from init_templates import CMD_PLACEHOLDER, _TEMPLATES_B85
except ImportError:  # pragma: no cover - used when run as a plain script
    from src.init_templates import CMD_PLACEHOLDER, _TEMPLATES_B85  # type: ignore

VERSION = "0.9.9"


# ---------------------------------------------------------------------------
# Small output / error helpers


def _write_stream(stream, data):
    if not data:
        return
    if isinstance(data, str):
        data = data.encode("utf-8", "surrogateescape")
    try:
        stream.write(data)
        stream.flush()
    except BrokenPipeError:
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, stream.fileno())
        except Exception:
            pass
    except OSError:
        # Rust's print helpers are best-effort for the outputs produced by
        # this program (most notably query results piped into `head`).
        pass


def out_text(data):
    _write_stream(sys.stdout.buffer, data)


def err_text(data):
    _write_stream(sys.stderr.buffer, data)


class CliExit(Exception):
    def __init__(self, code, stdout="", stderr=""):
        super().__init__(code)
        self.code = code
        self.stdout = stdout
        self.stderr = stderr


class ZoxideError(Exception):
    def __init__(self, message, causes=None):
        super().__init__(message)
        self.message = message
        self.causes = list(causes or [])

    def render(self):
        if not self.causes:
            return f"zoxide: {self.message}\n"
        if len(self.causes) == 1:
            return f"zoxide: {self.message}\n\nCaused by:\n    {self.causes[0]}\n"
        lines = [f"zoxide: {self.message}", "", "Caused by:"]
        for i, cause in enumerate(self.causes):
            lines.append(f"    {i}: {cause}")
        return "\n".join(lines) + "\n"


class FzfInterrupted(Exception):
    pass


def os_error_string(exc):
    if getattr(exc, "errno", None) is not None:
        return f"{os.strerror(exc.errno)} (os error {exc.errno})"
    return str(exc)


def has_surrogates(text):
    return any(0xD800 <= ord(ch) <= 0xDFFF for ch in text)


def lossy(text):
    """Convert a surrogate-escaped argument the way Rust lossy display does."""
    if not has_surrogates(text):
        return text
    return os.fsencode(text).decode("utf-8", "replace")


def display_path(text):
    return lossy(text)


def bin_name_from_argv0(argv0):
    if not argv0:
        return "zoxide"
    # Rust's Path::file_name semantics for ordinary Unix paths.
    trimmed = argv0.rstrip("/")
    if not trimmed:
        return "zoxide"
    name = trimmed.rsplit("/", 1)[-1]
    if name in ("", ".", ".."):
        return "zoxide"
    return lossy(name)


# ---------------------------------------------------------------------------
# Rust-flavoured scalar parsing / formatting


_FLOAT_RE = re.compile(
    r"^[+-]?(?:"
    r"(?i:inf(?:inity)?|nan)|"
    r"(?:(?:[0-9]+(?:\.[0-9]*)?)|(?:\.[0-9]+))(?:[eE][+-]?[0-9]+)?"
    r")$"
)


def parse_rust_f64(text):
    if text == "":
        raise ValueError("cannot parse float from empty string")
    if not _FLOAT_RE.match(text):
        raise ValueError("invalid float literal")
    try:
        return float(text)
    except Exception:
        raise ValueError("invalid float literal")


def parse_rust_uint(text, bits):
    if text == "":
        raise ValueError("cannot parse integer from empty string")
    body = text[1:] if text.startswith("+") else text
    if body == "" or any(not ("0" <= ch <= "9") for ch in body):
        raise ValueError("invalid digit found in string")
    value = int(body, 10)
    if value >= (1 << bits):
        raise ValueError("number too large to fit in target type")
    return value


def rust_max(a, b):
    if math.isnan(a):
        return b
    if math.isnan(b):
        return a
    if a == b:
        # Distinguish +0.0 from -0.0 the way Rust's f64::max does.
        return 0.0 if (a == 0.0) else a
    return a if a > b else b


def clamp_score(score):
    if math.isnan(score):
        return score
    if score < 0.0:
        return 0.0
    if score > 9999.0:
        return 9999.0
    return score


def format_score(score):
    score = clamp_score(score)
    if math.isnan(score):
        return "   NaN"
    return f"{score:6.1f}"


def total_cmp_key(value):
    bits = struct.unpack("<Q", struct.pack("<d", value))[0]
    if bits & (1 << 63):
        return ~bits & ((1 << 64) - 1)
    return bits | (1 << 63)


def now_seconds():
    return int(time.time())


def rust_utf8_error(data):
    """Return Rust's Utf8Error display text for invalid UTF-8 *data*."""
    i = 0
    n = len(data)
    while i < n:
        b0 = data[i]
        if b0 < 0x80:
            i += 1
            continue

        def invalid(length):
            return f"invalid utf-8 sequence of {length} bytes from index {i}"

        def incomplete():
            return f"incomplete utf-8 byte sequence from index {i}"

        if 0xC2 <= b0 <= 0xDF:
            if i + 1 >= n:
                return incomplete()
            if not (0x80 <= data[i + 1] <= 0xBF):
                return invalid(1)
            i += 2
            continue
        if 0xE0 <= b0 <= 0xEF:
            if i + 1 >= n:
                return incomplete()
            b1 = data[i + 1]
            lo = 0xA0 if b0 == 0xE0 else 0x80
            hi = 0x9F if b0 == 0xED else 0xBF
            if not (lo <= b1 <= hi):
                return invalid(1)
            if i + 2 >= n:
                return incomplete()
            if not (0x80 <= data[i + 2] <= 0xBF):
                return invalid(2)
            i += 3
            continue
        if 0xF0 <= b0 <= 0xF4:
            if i + 1 >= n:
                return incomplete()
            b1 = data[i + 1]
            lo = 0x90 if b0 == 0xF0 else 0x80
            hi = 0x8F if b0 == 0xF4 else 0xBF
            if not (lo <= b1 <= hi):
                return invalid(1)
            if i + 2 >= n:
                return incomplete()
            if not (0x80 <= data[i + 2] <= 0xBF):
                return invalid(2)
            if i + 3 >= n:
                return incomplete()
            if not (0x80 <= data[i + 3] <= 0xBF):
                return invalid(3)
            i += 4
            continue
        return invalid(1)
    return "invalid utf-8 sequence of 1 bytes from index 0"


# ---------------------------------------------------------------------------
# Paths, directories and configuration


def get_home_dir():
    home = os.environ.get("HOME")
    if home:
        return home
    try:
        entry = pwd.getpwuid(os.getuid())
    except Exception:
        return None
    return entry.pw_dir or None


def join_path(base, name):
    if base.endswith("/"):
        return base + name
    return base + "/" + name


def get_data_dir():
    if "_ZO_DATA_DIR" in os.environ:
        value = os.environ["_ZO_DATA_DIR"]
        if not value.startswith("/"):
            raise ZoxideError("_ZO_DATA_DIR must be an absolute path")
        return value

    xdg = os.environ.get("XDG_DATA_HOME")
    if xdg and xdg.startswith("/"):
        return join_path(xdg, "zoxide")
    home = get_home_dir()
    if home is None:
        # There is no useful fallback in this situation; mirror the Rust
        # behaviour of failing rather than writing somewhere surprising.
        raise ZoxideError("could not find data directory")
    return join_path(join_path(join_path(home, ".local"), "share"), "zoxide")


def lexical_resolve(path):
    if path.startswith("/"):
        combined = path
    else:
        try:
            cwd = os.getcwd()
        except OSError as exc:
            raise ZoxideError("could not get current directory", [os_error_string(exc)])
        combined = join_path(cwd, path) if path else cwd
    parts = []
    for segment in combined.split("/"):
        if segment in ("", "."):
            continue
        if segment == "..":
            if parts:
                parts.pop()
            continue
        parts.append(segment)
    return "/" + "/".join(parts)


def canonicalize_path(original):
    try:
        # strict=True is available from Python 3.10 onwards.
        return os.path.realpath(original, strict=True)  # type: ignore[call-arg]
    except TypeError:  # pragma: no cover
        resolved = os.path.realpath(original)
        if not os.path.lexists(resolved):
            raise ZoxideError(
                f"could not resolve path: {display_path(original)}",
                ["No such file or directory (os error 2)"],
            )
        return resolved
    except OSError as exc:
        raise ZoxideError(
            f"could not resolve path: {display_path(original)}",
            [os_error_string(exc)],
        )


def is_directory(path):
    try:
        return os.path.isdir(path)
    except Exception:
        return False


ROOT_COMPONENT = object()
CURDIR_COMPONENT = object()


def rust_components(path):
    components = []
    absolute = path.startswith("/")
    if absolute:
        components.append(ROOT_COMPONENT)
    seen_real = False
    for segment in path.split("/"):
        if segment == "":
            continue
        if segment == ".":
            if not absolute and not seen_real and CURDIR_COMPONENT not in components:
                components.append(CURDIR_COMPONENT)
            continue
        seen_real = True
        components.append(segment)
    return components


def path_starts_with(candidate, base):
    cand = rust_components(candidate)
    prefix = rust_components(base)
    return len(prefix) <= len(cand) and cand[: len(prefix)] == prefix


# ---------------------------------------------------------------------------
# Glob patterns (the Rust `glob` crate's syntax)


class GlobError(Exception):
    def __init__(self, pos, message):
        super().__init__(message)
        self.pos = pos
        self.message = message


class _GlobClass:
    __slots__ = ("negated", "items")

    def __init__(self, negated, items):
        self.negated = negated
        # items are ('char', ch) or ('range', lo, hi)
        self.items = items

    def regex(self):
        parts = []
        has_any = False
        for item in self.items:
            if item[0] == "char":
                parts.append(re.escape(item[1]))
                has_any = True
            else:
                _, lo, hi = item
                if lo <= hi:
                    parts.append(f"{re.escape(lo)}-{re.escape(hi)}")
                    has_any = True
        if not has_any:
            return r"[\s\S]" if self.negated else r"(?!)"
        body = "".join(parts)
        return f"[{'^' if self.negated else ''}{body}]"


def _parse_glob_class(pattern, start):
    n = len(pattern)
    j = start + 1
    negated = False
    if j < n and pattern[j] == "!":
        negated = True
        j += 1
    items = []
    # A ']' immediately after '[' or '[!' is a literal.
    if j < n and pattern[j] == "]":
        items.append(("char", "]"))
        j += 1
    while j < n and pattern[j] != "]":
        if j + 2 < n and pattern[j + 1] == "-" and pattern[j + 2] != "]":
            items.append(("range", pattern[j], pattern[j + 2]))
            j += 3
        else:
            items.append(("char", pattern[j]))
            j += 1
    if j >= n:
        raise GlobError(start, "invalid range pattern")
    return _GlobClass(negated, items), j + 1


class GlobPattern:
    # Token kinds: ('lit', ch), ('star',), ('rec',), ('any',), ('class', cls)
    def __init__(self, pattern):
        self.pattern = pattern
        tokens = []
        i = 0
        n = len(pattern)
        while i < n:
            ch = pattern[i]
            if ch == "*":
                if i + 1 < n and pattern[i + 1] == "*":
                    if i + 2 < n and pattern[i + 2] == "*":
                        raise GlobError(
                            i + 2,
                            "wildcards are either regular `*` or recursive `**`",
                        )
                    if i > 0 and pattern[i - 1] != "/":
                        raise GlobError(
                            i - 1,
                            "recursive wildcards must form a single path component",
                        )
                    if i + 2 < n and pattern[i + 2] != "/":
                        raise GlobError(
                            i + 2,
                            "recursive wildcards must form a single path component",
                        )
                    tokens.append(("rec",))
                    i += 2
                else:
                    tokens.append(("star",))
                    i += 1
            elif ch == "?":
                tokens.append(("any",))
                i += 1
            elif ch == "[":
                cls, i = _parse_glob_class(pattern, i)
                tokens.append(("class", cls))
            else:
                tokens.append(("lit", ch))
                i += 1
        self._regex = re.compile(self._tokens_to_regex(tokens), re.DOTALL)

    @staticmethod
    def _is_slash(token):
        return token[0] == "lit" and token[1] == "/"

    def _tokens_to_regex(self, tokens):
        parts = []
        i = 0
        n = len(tokens)
        while i < n:
            token = tokens[i]
            is_rec_start = token[0] == "rec" or (
                self._is_slash(token) and i + 1 < n and tokens[i + 1][0] == "rec"
            )
            if is_rec_start:
                segment_start = i
                leading_slash = False
                if self._is_slash(token):
                    leading_slash = True
                    i += 1
                # Consume one or more recursive components.
                while i < n and tokens[i][0] == "rec":
                    i += 1
                    if (
                        i + 1 < n
                        and self._is_slash(tokens[i])
                        and tokens[i + 1][0] == "rec"
                    ):
                        i += 1
                        continue
                    break
                trailing_slash = False
                if i < n and self._is_slash(tokens[i]):
                    trailing_slash = True
                    i += 1
                at_start = segment_start == 0
                at_end = i >= n
                if at_start and at_end:
                    parts.append(".*")
                elif at_end:
                    # A trailing /** (with or without a final slash in the
                    # pattern) requires something below the preceding part.
                    parts.append("/.*")
                elif at_start and not leading_slash:
                    parts.append("(?:.*/)?")
                else:
                    parts.append("/(?:.*/)?")
                continue
            if token[0] == "lit":
                parts.append(re.escape(token[1]))
            elif token[0] == "star":
                parts.append(".*")
            elif token[0] == "any":
                parts.append(".")
            elif token[0] == "class":
                parts.append(token[1].regex())
            i += 1
        return "".join(parts)

    def matches(self, text):
        return self._regex.fullmatch(text) is not None


def get_exclude_patterns():
    if "_ZO_EXCLUDE_DIRS" in os.environ:
        raw_patterns = os.environ["_ZO_EXCLUDE_DIRS"].split(":")
    else:
        home = get_home_dir()
        raw_patterns = [home] if home is not None else []
    patterns = []
    for raw in raw_patterns:
        try:
            patterns.append(GlobPattern(raw))
        except GlobError as exc:
            raise ZoxideError(
                f"invalid glob in _ZO_EXCLUDE_DIRS: {raw}",
                [f"Pattern syntax error near position {exc.pos}: {exc.message}"],
            )
    return patterns


def get_maxage():
    if "_ZO_MAXAGE" not in os.environ:
        return 10000
    raw = os.environ["_ZO_MAXAGE"]
    try:
        return parse_rust_uint(raw, 32)
    except ValueError as exc:
        raise ZoxideError(f"unable to parse _ZO_MAXAGE as integer: {raw}", [str(exc)])


def get_resolve_symlinks():
    return os.environ.get("_ZO_RESOLVE_SYMLINKS") == "1"


# ---------------------------------------------------------------------------
# Database


class DirEntry:
    __slots__ = ("path", "rank", "last_accessed")

    def __init__(self, path, rank, last_accessed):
        self.path = path
        self.rank = float(rank)
        self.last_accessed = int(last_accessed)

    def score(self, now):
        age = now - self.last_accessed if now >= self.last_accessed else 0
        if age < 3600:
            weight = 4.0
        elif age < 86400:
            weight = 2.0
        elif age < 604800:
            weight = 0.5
        else:
            weight = 0.25
        return self.rank * weight


class Database:
    def __init__(self, data_dir, db_path, dirs):
        self.data_dir = data_dir
        self.db_path = db_path
        self.dirs = dirs
        self.modified = False

    @classmethod
    def open(cls):
        data_dir = get_data_dir()
        db_path = join_path(data_dir, "db.zo")
        try:
            with open(db_path, "rb") as handle:
                contents = handle.read()
        except FileNotFoundError:
            try:
                os.makedirs(data_dir, exist_ok=True)
            except OSError as exc:
                raise ZoxideError(
                    f"unable to create data directory: {display_path(data_dir)}",
                    [os_error_string(exc)],
                )
            return cls(data_dir, db_path, [])
        except OSError as exc:
            raise ZoxideError(
                f"could not read from database: {display_path(db_path)}",
                [os_error_string(exc)],
            )

        if len(contents) < 4:
            raise ZoxideError("could not deserialize database: corrupted data")
        (version,) = struct.unpack_from("<I", contents, 0)
        if version != 3:
            raise ZoxideError(f"unsupported version (got {version}, supports 3)")

        offset = 4

        def fail(cause):
            raise ZoxideError("could not deserialize database", [cause])

        def read_primitive(fmt):
            nonlocal offset
            size = struct.calcsize(fmt)
            if offset + size > len(contents):
                fail("io error: unexpected end of file")
            (value,) = struct.unpack_from(fmt, contents, offset)
            offset += size
            return value

        count = read_primitive("<Q")
        dirs = []
        for _ in range(count):
            path_len = read_primitive("<Q")
            if offset + path_len > len(contents):
                fail("io error: ")
            raw_path = contents[offset : offset + path_len]
            offset += path_len
            try:
                path = raw_path.decode("utf-8")
            except UnicodeDecodeError:
                fail(f"string is not valid utf8: {rust_utf8_error(raw_path)}")
            rank = read_primitive("<d")
            last_accessed = read_primitive("<Q")
            dirs.append(DirEntry(path, rank, last_accessed))
        if offset != len(contents):
            fail("Slice had bytes remaining after deserialization")
        return cls(data_dir, db_path, dirs)

    def serialize(self):
        out = [struct.pack("<I", 3), struct.pack("<Q", len(self.dirs))]
        for entry in self.dirs:
            raw = entry.path.encode("utf-8", "surrogateescape")
            out.append(struct.pack("<Q", len(raw)))
            out.append(raw)
            out.append(struct.pack("<d", entry.rank))
            out.append(struct.pack("<Q", entry.last_accessed & ((1 << 64) - 1)))
        return b"".join(out)

    def save(self):
        if not self.modified:
            return
        payload = self.serialize()
        alphabet = string.ascii_letters + string.digits
        suffix = "".join(random.SystemRandom().choice(alphabet) for _ in range(12))
        tmp_path = join_path(self.data_dir, f"tmp_{suffix}")
        try:
            handle = open(tmp_path, "wb")
        except OSError as exc:
            raise ZoxideError(
                "could not write to database",
                [f"could not create file: {display_path(tmp_path)}", os_error_string(exc)],
            )
        try:
            with handle:
                handle.write(payload)
        except OSError as exc:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise ZoxideError(
                "could not write to database",
                [f"could not write to file: {display_path(tmp_path)}", os_error_string(exc)],
            )
        try:
            os.replace(tmp_path, self.db_path)
        except OSError as exc:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise ZoxideError(
                "could not write to database",
                [f"could not rename file: {display_path(tmp_path)}", os_error_string(exc)],
            )
        self.modified = False

    def save_silently(self):
        try:
            self.save()
        except Exception:
            pass

    def _swap_remove(self, index):
        last = self.dirs.pop()
        if index < len(self.dirs):
            self.dirs[index] = last

    def find(self, path):
        for index, entry in enumerate(self.dirs):
            if entry.path == path:
                return index
        return None

    def add(self, path, by, now):
        index = self.find(path)
        if index is not None:
            entry = self.dirs[index]
            entry.rank = rust_max(entry.rank + by, 0.0)
            entry.last_accessed = now
        else:
            self.dirs.append(DirEntry(path, rust_max(by, 0.0), now))
        self.modified = True

    def edit_adjust(self, path, by, now):
        index = self.find(path)
        if index is not None:
            entry = self.dirs[index]
            entry.rank = rust_max(entry.rank + by, 0.0)
        else:
            self.dirs.append(DirEntry(path, rust_max(by, 0.0), now))
        self.modified = True

    def remove_exact(self, path):
        index = self.find(path)
        if index is None:
            return False
        self._swap_remove(index)
        self.modified = True
        return True

    def sort_by_score(self, now):
        self.dirs.sort(key=lambda entry: total_cmp_key(entry.score(now)))
        self.modified = True

    def dedup(self):
        self.dirs.sort(key=lambda entry: entry.path.encode("utf-8", "surrogateescape"))
        for i in range(len(self.dirs) - 1, 0, -1):
            if i >= len(self.dirs):
                continue
            if self.dirs[i - 1].path == self.dirs[i].path:
                self.dirs[i - 1].rank += self.dirs[i].rank
                if self.dirs[i].last_accessed > self.dirs[i - 1].last_accessed:
                    self.dirs[i - 1].last_accessed = self.dirs[i].last_accessed
                self._swap_remove(i)

    def age(self, maxage):
        total = 0.0
        for entry in self.dirs:
            total += entry.rank
        if not (total > float(maxage)):
            return
        factor = 0.9 * float(maxage) / total
        for i in range(len(self.dirs) - 1, -1, -1):
            if i >= len(self.dirs):
                continue
            self.dirs[i].rank *= factor
            if self.dirs[i].rank < 1.0:
                self._swap_remove(i)


