# Clap-like argument parsing


def _jaro(s, t):
    if s == t:
        return 1.0
    len_s, len_t = len(s), len(t)
    if len_s == 0 or len_t == 0:
        return 0.0
    search_range = max(max(len_s, len_t) // 2 - 1, 0)
    s_matches = [False] * len_s
    t_matches = [False] * len_t
    matches = 0
    for i, ch in enumerate(s):
        lo = max(0, i - search_range)
        hi = min(len_t, i + search_range + 1)
        for j in range(lo, hi):
            if not t_matches[j] and t[j] == ch:
                s_matches[i] = True
                t_matches[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    mismatches = 0
    k = 0
    for i in range(len_s):
        if s_matches[i]:
            while not t_matches[k]:
                k += 1
            if s[i] != t[k]:
                mismatches += 1
            k += 1
    transpositions = mismatches // 2
    return (matches / len_s + matches / len_t + (matches - transpositions) / matches) / 3.0


def _jaro_winkler(s, t):
    jaro = _jaro(s, t)
    if jaro > 0.7:
        prefix = 0
        for a, b in zip(s, t):
            if a == b and prefix < 4:
                prefix += 1
            else:
                break
        return jaro + prefix * 0.1 * (1.0 - jaro)
    return jaro


def _did_you_mean(value, candidates):
    scored = []
    for candidate in candidates:
        confidence = _jaro_winkler(value, candidate)
        if confidence > 0.7:
            scored.append((confidence, candidate))
    scored.sort(key=lambda item: item[0])
    return [candidate for _, candidate in scored]


def _format_suggestions(candidates, noun):
    if len(candidates) == 1:
        return f"a similar {noun} exists: '{candidates[0]}'"
    joined = ", ".join(f"'{candidate}'" for candidate in candidates)
    return f"some similar {noun}s exist: {joined}"


class OptionSpec:
    def __init__(
        self,
        id,
        long,
        short=None,
        value_name=None,
        kind="bool",
        possible=None,
        allow_empty=False,
        required=False,
    ):
        self.id = id
        self.long = long
        self.short = short
        self.value_name = value_name
        self.kind = kind
        self.possible = possible
        self.allow_empty = allow_empty
        self.required = required

    @property
    def takes_value(self):
        return self.kind != "bool"

    @property
    def display(self):
        if self.takes_value:
            return f"--{self.long} {self.value_name}"
        return f"--{self.long}"

    @property
    def render(self):
        return self.display


_HELP_OPT = OptionSpec("__help", "help", "h")
_VERSION_OPT = OptionSpec("__version", "version", "V")


class PositionalSpec:
    def __init__(self, id, display, required=False, multi=False, kind="string", possible=None, allow_empty=True):
        self.id = id
        self.display = display
        self.required = required
        self.multi = multi
        self.kind = kind
        self.possible = possible
        self.allow_empty = allow_empty

    @property
    def required_display(self):
        if self.id in ("paths", "keywords"):
            return f"<{self.id.upper()}>..."
        return self.display


class CommandSpec:
    def __init__(self, key, path, usage, options, positional=None):
        self.key = key
        self.path = path
        self.usage_template = usage
        self.options = options
        self.positional = positional

    def full_usage(self, bin_name):
        return self.usage_template.replace("{bin}", bin_name)

    def all_options(self):
        return list(self.options) + [_HELP_OPT, _VERSION_OPT]

    def find_long(self, name):
        for option in self.options:
            if option.long == name:
                return option
        return None

    def find_short(self, ch):
        for option in self.options:
            if option.short == ch:
                return option
        return None


