# Query matching


def _is_match(path, keywords_lower):
    if not keywords_lower:
        return True
    rest = path.lower()
    for keyword in keywords_lower[:-1]:
        index = rest.find(keyword)
        if index < 0:
            return False
        rest = rest[index + len(keyword) :]
    last = keywords_lower[-1]
    index = rest.rfind(last)
    if index < 0:
        return False
    return "/" not in rest[index + len(last) :]


