def run_edit_subcommand(key, values, positionals):
    db = Database.open()
    now = now_seconds()
    if key == "edit-reload":
        _edit_print(db, now)
        return 0
    path = positionals[0]
    if key == "edit-delete":
        if db.remove_exact(path):
            db.save()
