def _rust_lines(content):
    if content == "":
        return []
    parts = content.split("\n")
    ends_with_newline = content.endswith("\n")
    if ends_with_newline:
        parts.pop()
    lines = []
    for index, part in enumerate(parts):
        terminated = ends_with_newline or index < len(parts) - 1
        if terminated and part.endswith("\r"):
            part = part[:-1]
        lines.append(part)
    return lines


def _import_error(causes):
    return ZoxideError("import error", causes)


def _sigmoid(rank):
    try:
        return 1.0 / (1.0 + math.exp(-rank))
    except OverflowError:
        return 0.0


def run_import(values, positionals):
    source = positionals[0]
    try:
        with open(source, "rb") as handle:
            raw_content = handle.read()
    except OSError as exc:
        raise ZoxideError(
            f"could not open database for importing: {display_path(source)}",
            [os_error_string(exc)],
        )
    try:
        content = raw_content.decode("utf-8")
    except UnicodeDecodeError:
        raise ZoxideError(
            f"could not open database for importing: {display_path(source)}",
            ["stream did not contain valid UTF-8"],
        )

    db = Database.open()
    if db.dirs and not values.get("merge"):
        raise ZoxideError(
            "current database is not empty, specify --merge to continue anyway"
        )

    imported = []
    from_format = values.get("from")
    for line in _rust_lines(content):
        if line == "":
            continue
        if from_format == "z":
            segments = line.rsplit("|", 2)
            epoch_text = segments[-1]
            try:
                epoch = parse_rust_uint(epoch_text, 64)
            except ValueError as exc:
                raise _import_error([f"invalid epoch: {epoch_text}", str(exc)])
            if len(segments) < 2:
                raise _import_error([f"invalid entry: {line}"])
            rank_text = segments[-2]
            try:
                rank = parse_rust_f64(rank_text)
            except ValueError as exc:
                raise _import_error([f"invalid rank: {rank_text}", str(exc)])
            if len(segments) < 3:
                raise _import_error([f"invalid entry: {line}"])
            imported.append(DirEntry(segments[0], rank, epoch))
        else:  # autojump
            if "\t" not in line:
                raise _import_error([f"invalid entry: {line}"])
            rank_text, path = line.split("\t", 1)
            try:
                rank = parse_rust_f64(rank_text)
            except ValueError as exc:
                raise _import_error([f"invalid rank: {rank_text}", str(exc)])
            imported.append(DirEntry(path, _sigmoid(rank), 0))

    if imported:
        db.dirs.extend(imported)
        db.modified = True
        db.dedup()
        db.save()
    return 0


