class FzfProcess:
    def __init__(self, proc):
        self.proc = proc

    @classmethod
    def spawn(cls, edit=False):
        env = dict(os.environ)
        argv = ["fzf"] + _FZF_COMMON
        if edit:
            argv += _FZF_EDIT_DEFAULTS
        elif "_ZO_FZF_OPTS" in os.environ:
            env["FZF_DEFAULT_OPTS"] = os.environ["_ZO_FZF_OPTS"]
        else:
            argv += _FZF_QUERY_DEFAULTS
        try:
            proc = subprocess.Popen(
                argv,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=None,
                env=env,
            )
        except FileNotFoundError:
            raise ZoxideError("could not find fzf, is it installed?")
        except OSError as exc:
            if exc.errno == errno.ENOENT:
                raise ZoxideError("could not find fzf, is it installed?")
            raise ZoxideError("could not launch fzf", [os_error_string(exc)])
        return cls(proc)

    def communicate(self, input_data):
        try:
            output, _ = self.proc.communicate(input=input_data)
        except BrokenPipeError:
            output = b""
        try:
            selection = output.decode("utf-8")
        except UnicodeDecodeError:
            raise ZoxideError(
                "failed to read from fzf", ["stream did not contain valid UTF-8"]
            )
        code = self.proc.returncode
        if code is not None and code < 0:
            raise ZoxideError("fzf was terminated")
        if code == 0:
            return selection
        if code == 1:
            raise ZoxideError("no match found")
        if code == 2:
            raise ZoxideError("fzf returned an error")
        if code == 130:
            raise FzfInterrupted()
        if code is not None and 128 <= code <= 254:
            raise ZoxideError("fzf was terminated")
        raise ZoxideError("fzf returned an unknown error")


# ---------------------------------------------------------------------------
# Query matching


def _is_match(path, keywords_lower):
    if not keywords_lower:
        return True
    rest = path.lower()
    for keyword in keywords_lower[:-1]:
        index = rest.find(keyword)
        if index < 0:
            return False
        rest = rest[index + len(keyword) :]
    last = keywords_lower[-1]
    index = rest.rfind(last)
    if index < 0:
        return False
    return "/" not in rest[index + len(last) :]


