# Subcommand implementations


def _load_init_templates():
    import base64
    import json
    import zlib

    return json.loads(zlib.decompress(base64.b85decode(_TEMPLATES_B85)))


_INIT_TEMPLATES = None


def run_init(values, positionals):
    global _INIT_TEMPLATES
    if _INIT_TEMPLATES is None:
        _INIT_TEMPLATES = _load_init_templates()
    shell = positionals[0]
    hook = values.get("hook", "pwd")
    echo = 1 if os.environ.get("_ZO_ECHO") == "1" else 0
    resolve = 1 if os.environ.get("_ZO_RESOLVE_SYMLINKS") == "1" else 0
    no_cmd = 1 if values.get("no_cmd") else 0
    text = _INIT_TEMPLATES[f"{shell}|{hook}|{echo}|{resolve}|{no_cmd}"]
    if not no_cmd:
        text = text.replace(CMD_PLACEHOLDER, values.get("cmd", "z"))
    out_text(text)
    return 0


def run_add(values, positionals):
    exclude_patterns = get_exclude_patterns()
    maxage = get_maxage()
    resolve_symlinks = get_resolve_symlinks()
    score = values.get("score", 1.0)
    db = Database.open()
    now = now_seconds()
    added_any = False
    for original in positionals:
        if resolve_symlinks:
            resolved = canonicalize_path(original)
        else:
            resolved = lexical_resolve(original)
        if has_surrogates(resolved):
            raise ZoxideError(f"invalid unicode in path: {display_path(resolved)}")
        if any(pattern.matches(resolved) for pattern in exclude_patterns):
            continue
        if not is_directory(resolved):
            raise ZoxideError(f"not a directory: {resolved}")
        db.add(resolved, score, now)
        added_any = True
    if added_any:
        db.age(maxage)
    db.save()
    return 0


def run_query(values, positionals):
    db = Database.open()
    exclude_patterns = get_exclude_patterns()
    now = now_seconds()
    db.sort_by_score(now)

    keywords_lower = [keyword.lower() for keyword in positionals]
    all_dirs = bool(values.get("all"))
    base_dir = values.get("base_dir")
    exclude = values.get("exclude")

    def candidates():
        index = len(db.dirs)
        while index > 0:
            index -= 1
            entry = db.dirs[index]
            path = entry.path
            rank = entry.rank
            last_accessed = entry.last_accessed
            if not _is_match(path, keywords_lower):
                continue
            if base_dir is not None and not path_starts_with(path, base_dir):
                continue
            if any(pattern.matches(path) for pattern in exclude_patterns):
                db._swap_remove(index)
                db.modified = True
                continue
            if not all_dirs and not is_directory(path):
                continue
            yield DirEntry(path, rank, last_accessed)

    def format_entry(entry, separator):
        if values.get("score"):
            return f"{format_score(entry.score(now))}{separator}{entry.path}"
        return entry.path

    if values.get("interactive"):
        try:
            fzf = FzfProcess.spawn(edit=False)
        except ZoxideError:
            db.save_silently()
            raise
        choices = []
        for entry in candidates():
            if exclude is not None and entry.path == exclude:
                continue
            choices.append(f"{format_score(entry.score(now))}\t{entry.path}\0")
        input_data = "".join(choices).encode("utf-8", "surrogateescape")
        try:
            selection = fzf.communicate(input_data)
        except FzfInterrupted:
            db.save_silently()
            return 130
        except ZoxideError:
            db.save_silently()
            raise
        if values.get("score"):
            output = selection
        else:
            raw = selection.encode("utf-8")
            if len(raw) < 7 or (len(raw) > 7 and 0x80 <= raw[7] <= 0xBF):
                db.save_silently()
                raise ZoxideError("could not read selection from fzf")
            try:
                output = raw[7:].decode("utf-8")
            except UnicodeDecodeError:
                db.save_silently()
                raise ZoxideError("could not read selection from fzf")
        out_text(output)
        db.save()
        return 0

    if values.get("list"):
        lines = []
        for entry in candidates():
            if exclude is not None and entry.path == exclude:
                continue
            if values.get("score"):
                lines.append(f"{format_score(entry.score(now))} {entry.path}\n")
            else:
                lines.append(f"{entry.path}\n")
        out_text("".join(lines))
        db.save()
        return 0

    found = None
    found_excluded = False
    for entry in candidates():
        if exclude is not None and entry.path == exclude:
            found_excluded = True
            continue
        found = entry
        break
    if found is None:
        db.save_silently()
        if found_excluded:
            raise ZoxideError("you are already in the only match")
        raise ZoxideError("no match found")
    if values.get("score"):
        out_text(f"{format_score(found.score(now))} {found.path}\n")
    else:
        out_text(f"{found.path}\n")
    db.save()
    return 0


def run_remove(values, positionals):
    db = Database.open()
    for raw in positionals:
        if db.remove_exact(raw):
            continue
        resolved = lexical_resolve(raw)
        if db.remove_exact(resolved):
            continue
        raise ZoxideError(f"path not found in database: {raw}")
    db.save()
    return 0


def _edit_print(db, now):
    pieces = []
    for entry in reversed(db.dirs):
        pieces.append(f"{format_score(entry.score(now))}\t{entry.path}\0")
    out_text("".join(pieces))


def run_edit_main():
    db = Database.open()
    now = now_seconds()
    db.sort_by_score(now)
    db.save()
    fzf = FzfProcess.spawn(edit=True)
    try:
        fzf.communicate(b"")
    except FzfInterrupted:
        return 130
    return 0


def run_edit_subcommand(key, values, positionals):
    db = Database.open()
    now = now_seconds()
    if key == "edit-reload":
        _edit_print(db, now)
        return 0
    path = positionals[0]
    if key == "edit-delete":
        if db.remove_exact(path):
            db.save()
        _edit_print(db, now)
        return 0
    by = 1.0 if key == "edit-increment" else -1.0
    db.edit_adjust(path, by, now)
    db.save()
    _edit_print(db, now)
    return 0


def _rust_lines(content):
    if content == "":
        return []
    parts = content.split("\n")
    ends_with_newline = content.endswith("\n")
    if ends_with_newline:
        parts.pop()
    lines = []
    for index, part in enumerate(parts):
        terminated = ends_with_newline or index < len(parts) - 1
        if terminated and part.endswith("\r"):
            part = part[:-1]
        lines.append(part)
    return lines


def _import_error(causes):
    return ZoxideError("import error", causes)


def _sigmoid(rank):
    try:
        return 1.0 / (1.0 + math.exp(-rank))
    except OverflowError:
        return 0.0


def run_import(values, positionals):
    source = positionals[0]
    try:
        with open(source, "rb") as handle:
            raw_content = handle.read()
    except OSError as exc:
        raise ZoxideError(
            f"could not open database for importing: {display_path(source)}",
            [os_error_string(exc)],
        )
    try:
        content = raw_content.decode("utf-8")
    except UnicodeDecodeError:
        raise ZoxideError(
            f"could not open database for importing: {display_path(source)}",
            ["stream did not contain valid UTF-8"],
        )

    db = Database.open()
    if db.dirs and not values.get("merge"):
        raise ZoxideError(
            "current database is not empty, specify --merge to continue anyway"
        )

    imported = []
    from_format = values.get("from")
    for line in _rust_lines(content):
        if line == "":
            continue
        if from_format == "z":
            segments = line.rsplit("|", 2)
            epoch_text = segments[-1]
            try:
                epoch = parse_rust_uint(epoch_text, 64)
            except ValueError as exc:
                raise _import_error([f"invalid epoch: {epoch_text}", str(exc)])
            if len(segments) < 2:
                raise _import_error([f"invalid entry: {line}"])
            rank_text = segments[-2]
            try:
                rank = parse_rust_f64(rank_text)
            except ValueError as exc:
                raise _import_error([f"invalid rank: {rank_text}", str(exc)])
            if len(segments) < 3:
                raise _import_error([f"invalid entry: {line}"])
            imported.append(DirEntry(segments[0], rank, epoch))
        else:  # autojump
            if "\t" not in line:
                raise _import_error([f"invalid entry: {line}"])
            rank_text, path = line.split("\t", 1)
            try:
                rank = parse_rust_f64(rank_text)
            except ValueError as exc:
                raise _import_error([f"invalid rank: {rank_text}", str(exc)])
            imported.append(DirEntry(path, _sigmoid(rank), 0))

    if imported:
        db.dirs.extend(imported)
        db.modified = True
        db.dedup()
        db.save()
    return 0


# ---------------------------------------------------------------------------
# Top-level dispatch


_TOP_COMMANDS = ["add", "edit", "import", "init", "query", "remove"]
_EDIT_COMMANDS = ["decrement", "delete", "increment", "reload"]
_EDIT_COMMAND_SET = {"reload", "delete", "increment", "decrement"}


def _parse_flag_only_command(spec, bin_name, args, allow_subcommands):
    """Parse top/edit headers.

    Returns (subcommand_token_or_None, remaining_args, had_double_dash).
    Raises CliExit for help/version/errors, and returns None when the
    command should run with no subcommand.
    """
    errors = _ClapErrors(bin_name)
    i = 0
    while i < len(args):
        token = args[i]
        if token == "--":
            if i + 1 >= len(args):
                return None, [], True
            return args[i + 1], args[i + 2 :], True
        if token.startswith("--") and len(token) > 2:
            body = token[2:]
            if "=" in body:
                name, value = body.split("=", 1)
                has_eq = True
            else:
                name, value, has_eq = body, None, False
            if name == "help":
                if has_eq:
                    # Reuse Parser's formatting for this rare shape.
                    Parser(spec, bin_name).unexpected_value(_HELP_OPT, value)
                raise CliExit(0, stdout=_help_text(spec.key, bin_name))
            if name == "version":
                if has_eq:
                    Parser(spec, bin_name).unexpected_value(_VERSION_OPT, value)
                raise CliExit(0, stdout=f"{_VERSION_NAMES[spec.key]} {VERSION}\n")
            Parser(spec, bin_name).unknown_long(name)
        if token.startswith("-") and len(token) > 1:
            for ch in token[1:]:
                if ch == "h":
                    raise CliExit(0, stdout=_help_text(spec.key, bin_name))
                if ch == "V":
                    raise CliExit(0, stdout=f"{_VERSION_NAMES[spec.key]} {VERSION}\n")
                Parser(spec, bin_name).unknown_short(ch)
            i += 1
            continue
        return token, args[i + 1 :], False
    return None, [], False


def dispatch(argv, bin_name):
    top_spec = SPECS["top"]
    if not argv:
        raise CliExit(2, stderr=_help_text("top", bin_name))
    token, rest, after_dashdash = _parse_flag_only_command(top_spec, bin_name, argv, True)
    if token is None:
        raise CliExit(2, stderr=_help_text("top", bin_name))
    if after_dashdash:
        if token in _TOP_COMMANDS:
            errors = _ClapErrors(bin_name)
            errors.generic(
                f"unexpected argument '{lossy(token)}' found",
                top_spec.full_usage(bin_name),
                tip=f"subcommand '{lossy(token)}' exists; to use it, remove the '--' before it",
            )
        _unknown_subcommand(bin_name, "top", token, _TOP_COMMANDS, top_spec.full_usage(bin_name))
    if token not in _TOP_COMMANDS:
        _unknown_subcommand(bin_name, "top", token, _TOP_COMMANDS, top_spec.full_usage(bin_name))

    if token == "edit":
        return dispatch_edit(rest, bin_name)

    spec = SPECS[token]
    values, positionals = Parser(spec, bin_name).parse(rest)
    if token == "add":
        return run_add(values, positionals)
    if token == "import":
        return run_import(values, positionals)
    if token == "init":
        return run_init(values, positionals)
    if token == "query":
        return run_query(values, positionals)
    if token == "remove":
        return run_remove(values, positionals)
    return 0


def dispatch_edit(args, bin_name):
    spec = SPECS["edit"]
    token, rest, after_dashdash = _parse_flag_only_command(spec, bin_name, args, True)
    if token is None:
        return run_edit_main()
    if after_dashdash:
        if token in _EDIT_COMMAND_SET:
            errors = _ClapErrors(bin_name)
            errors.generic(
                f"unexpected argument '{lossy(token)}' found",
                spec.full_usage(bin_name),
                tip=f"subcommand '{lossy(token)}' exists; to use it, remove the '--' before it",
            )
        _unknown_subcommand(bin_name, "edit", token, _EDIT_COMMANDS, spec.full_usage(bin_name))
    if token not in _EDIT_COMMAND_SET:
        _unknown_subcommand(bin_name, "edit", token, _EDIT_COMMANDS, spec.full_usage(bin_name))
    key = f"edit-{token}"
    values, positionals = Parser(SPECS[key], bin_name).parse(rest)
    return run_edit_subcommand(key, values, positionals)


def main(argv=None):
    if argv is None:
        argv = sys.argv
    bin_name = bin_name_from_argv0(argv[0] if argv else "")
    try:
        result = dispatch(argv[1:], bin_name)
        return int(result or 0)
    except CliExit as exc:
        if exc.stdout:
            out_text(exc.stdout)
        if exc.stderr:
            err_text(exc.stderr)
        return exc.code
    except ZoxideError as exc:
        err_text(exc.render())
        return 1
    except BrokenPipeError:
        return 0


if __name__ == "__main__":
    sys.exit(main())
