            usage,
        )
'''
new='''    def unexpected_value(self, option, value):
        if self.used:
            group_items = []
            if self.spec.positional is not None:
                plain = self.spec.positional.display.strip("<>[]").removesuffix("...")
                group_items.append(plain)
            group_items.extend(opt.render for opt in self.spec.options)
            group = "<" + "|".join(group_items) + ">"
            base = " ".join([self.bin] + self.spec.path)
            if option.id in ("__help", "__version"):
                usage = f"{base} {option.render} {group}"
            else:
                usage = f"{base} {group}"
        else:
            parts = [self.bin] + self.spec.path
            for opt in self.spec.options:
                if opt.required:
                    parts.append(opt.render)
            if option.id not in [opt.id for opt in self.spec.options if opt.required]:
                parts.append(option.render)
            if self.spec.key == "top":
                parts.append("<COMMAND>")
            elif self.spec.positional is not None:
                parts.append(self.spec.positional.display)
            usage = " ".join(parts)
        self.errors.generic(
            f"unexpected value '{lossy(value)}' for '--{option.long}' found; no more were expected",
            usage,
        )
'''
assert old in s; s=s.replace(old,new)

# assign_option deferred wrapping: replace whole method
start=s.index("    def assign_option(self, option, raw):\n")
end=s.index("    def assign_positional(self, token):\n",start)
new_assign='''    def assign_option(self, option, raw):
        try:
            if raw == "" and not option.allow_empty:
                self.value_required_option(option)
            if option.kind == "enum":
                shown = lossy(raw)
                if shown not in option.possible:
                    self.invalid_enum(option.display, shown, option.possible)
                self.values[option.id] = shown
                return
            if has_surrogates(raw):
                self.invalid_utf8()
            if option.kind == "float":
                try:
                    self.values[option.id] = parse_rust_f64(raw)
                except ValueError as exc:
                    self.errors.no_usage(
                        f"invalid value '{raw}' for '{option.display}': {exc}"
                    )
                return
            self.values[option.id] = raw
        except CliExit as exc:
            self.set_pending(exc, ("option", option.id))
            if option.kind == "float":
                self.values[option.id] = 0.0
            elif option.kind == "enum":
                self.values[option.id] = lossy(raw)
            else:
                self.values[option.id] = raw

'''
s=s[:start]+new_assign+s[end:]

# assign_positional deferred validation
start=s.index("    def assign_positional(self, token):\n")
end=s.index("    def _classify_flag_token(self, token):\n",start)
new_pos='''    def assign_positional(self, token):
        positional = self.spec.positional
        if positional is None:
            self.unexpected_positional(token)
        if not positional.multi and self.positionals:
            self.unexpected_positional(token)
        try:
            if token == "" and not positional.allow_empty:
                self.value_required_positional(positional)
            if positional.kind == "enum":
                shown = lossy(token)
                if shown not in positional.possible:
                    self.invalid_enum(positional.display, shown, positional.possible)
                self.positionals.append(shown)
                return
            if positional.kind == "string" and has_surrogates(token):
                self.invalid_utf8()
        except CliExit as exc:
            self.set_pending(exc, ("positional", positional.id))
            self.positionals.append(lossy(token) if positional.kind == "enum" else token)
            return
        self.positionals.append(token)

'''
s=s[:start]+new_pos+s[end:]

# _next_option_value missing deferred
start=s.index("    def _next_option_value(self, option, args, i):\n")
end=s.index("    def parse(self, args):\n",start)
new_next='''    def _next_option_value(self, option, args, i):
        """Return (value, new_index); value is None for a deferred missing error."""
        def missing(next_i):
            try:
                self.value_required_option(option)
            except CliExit as exc:
                self.set_pending(exc, ("option", option.id))
            return None, next_i

        if i + 1 >= len(args):
            return missing(len(args))
        nxt = args[i + 1]
        if nxt == "--":
            return missing(i + 1)
        if nxt.startswith("-") and len(nxt) > 1:
            classification = self._classify_flag_token(nxt)
            if classification == "known":
                return missing(i + 1)
            if nxt.startswith("--"):
                self.unknown_long(nxt[2:].split("=", 1)[0])
            for ch in nxt[1:]:
                if ch in ("h", "V"):
                    continue
                option2 = self.spec.find_short(ch)
                if option2 is None:
                    self.unknown_short(ch)
                if option2.takes_value:
                    break
            self.unknown_short(nxt[1])
        return nxt, i + 2

'''
s=s[:start]+new_next+s[end:]

p.write_text(s)
print("patched part1")
