import pathlib
p=pathlib.Path("src/zoxide.py"); s=p.read_text()
start=s.index("def _write_stream(stream, data):")
end=s.index("def err_text(data):",start)
# replace through err_text function (find following blank / class)
end2=s.index("\n\nclass CliExit",end)
new='''def _write_best_effort(fd, data):
    if not data:
        return
    if isinstance(data, str):
        data = data.encode("utf-8", "surrogateescape")
    view = memoryview(data)
    while view:
        try:
            written = os.write(fd, view)
        except InterruptedError:
            continue
        except OSError:
            return
        view = view[written:]


def out_text(data):
    _write_best_effort(1, data)


def err_text(data):
    _write_best_effort(2, data)


class BrokenPipeApp(Exception):
    pass


def app_out(data, message="could not write to stdout"):
    if isinstance(data, str):
        data = data.encode("utf-8", "surrogateescape")
    view = memoryview(data)
    while view:
        try:
            written = os.write(1, view)
        except InterruptedError:
            continue
        except BrokenPipeError:
            raise BrokenPipeApp()
        except OSError as exc:
            if exc.errno == errno.EPIPE:
                raise BrokenPipeApp()
            raise ZoxideError(message, [os_error_string(exc)])
        view = view[written:]
'''
s=s[:start]+new+s[end2:]
# Need ZoxideError referenced in app_out defined later at runtime, fine.
# run_init output
s=s.replace('    out_text(text)\n    return 0\n\n\ndef run_add', '    try:\n        app_out(text)\n    except BrokenPipeApp:\n        pass\n    return 0\n\n\ndef run_add')
p.write_text(s)
PY
python3 -m py_compile src/zoxide.py && echo ok"}

